param([string]$AfterFxPath="C:\Program Files\Adobe\Adobe After Effects 2025\Support Files\AfterFX.exe")
$ErrorActionPreference="Stop";$root=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path;$config=Join-Path $env:LOCALAPPDATA "EditFlow2\bridge-config.json";$dir=Join-Path $root "proofs\artifacts\m3-marker-motion-p4-fast-regression";$core=Join-Path $dir "core-result.json";$result=Join-Path $dir "result.json";$clean=Join-Path $root "scripts\windows\cleanup-m3-marker-motion-stale-proof.jsx";$arm=Join-Path $root "scripts\windows\arm-m3-marker-motion-p4-proof.jsx";$disarm=Join-Path $root "scripts\windows\disarm-m3-marker-motion-p4-proof.jsx";$verify=Join-Path $root "scripts\windows\verify-blank-unsaved-ae.jsx";$cli=Join-Path $root "scripts\m3-marker-motion-p4-fast-regression.mjs";$cleanEv=Join-Path $env:TEMP "EditFlow2-m3-marker-motion-stale-cleanup.txt";$armEv=Join-Path $env:TEMP "EditFlow2-m3-marker-motion-p4-arm.txt";$disarmEv=Join-Path $env:TEMP "EditFlow2-m3-marker-motion-p4-disarm.txt";$verifyEv=Join-Path $env:TEMP "EditFlow2-blank-unsaved-proof.txt";$start=Get-Date;$exit=1
function Ae([string]$script,[string]$ev,[string]$prefix){if(Test-Path $ev){Remove-Item $ev -Force};[void](Start-Process -FilePath $AfterFxPath -ArgumentList @("-r",$script)-PassThru);$d=(Get-Date).AddSeconds(4);while((Get-Date)-lt $d){if(Test-Path $ev){$v=(Get-Content $ev -Raw).Trim();if($v.StartsWith($prefix,[StringComparison]::Ordinal)){return $v};throw "AE helper '$script' returned '$v'."};Start-Sleep -Milliseconds 50};throw "AE helper '$script' timed out."}
try{New-Item -ItemType Directory -Force -Path $dir|Out-Null;foreach($p in @($core,$result)){if(Test-Path $p){Remove-Item $p -Force}};$before=Ae $clean $cleanEv "CLEANED ";$blank=Ae $verify $verifyEv "BLANK_UNSAVED";Write-Host "Regression preflight: $before; $blank";$a=Ae $arm $armEv "ARMED";Write-Host "P4 gate: $a";Push-Location $root;try{npm run build:test-runtime;if($LASTEXITCODE -ne 0){throw "Runtime build failed"};& node $cli --config $config --result $core;$node=$LASTEXITCODE}finally{Pop-Location};$after=Ae $clean $cleanEv "CLEANED ";$blankAfter=Ae $verify $verifyEv "BLANK_UNSAVED";$coreObj=if(Test-Path $core){Get-Content $core -Raw|ConvertFrom-Json}else{$null};$elapsed=[int]((Get-Date)-$start).TotalMilliseconds;$ok=$node -eq 0 -and $null -ne $coreObj -and $coreObj.ok -eq $true -and $blankAfter -eq "BLANK_UNSAVED";$final=[ordered]@{proofId="M3_MARKER_MOTION_P4_FAST_REGRESSION";status=if($ok){"PASS"}else{"FAILURE"};ok=$ok;elapsedMs=$elapsed;speedTargetMs=30000;speedTargetMet=$elapsed -le 30000;core=$coreObj;preCleanup=$before;postCleanup=$after;cleanupComplete=$blankAfter -eq "BLANK_UNSAVED"};$final|ConvertTo-Json -Depth 20|Out-File $result -Encoding utf8;Get-Content $result -Raw|Write-Host;$exit=if($ok){0}else{1}}catch{Write-Error $_;$exit=1}finally{try{$d=Ae $disarm $disarmEv "DISARMED";Write-Host "P4 gate: $d"}catch{Write-Error $_;$exit=1}};exit $exit
